interface IconProps {
  name: string;
  size?: number;
  color?: string;
  style?: StyleProp<ViewStyle>;
  strokeWidth?: number;
}

const Icon: React.FC<IconProps> = ({
  name,
  size = 24,
  color = Colors.neutral[50],
  style,
  strokeWidth = 1.75,
}) => {
  if (name === 'at') return <AtLineIcon size={size} color={color} style={style} />;
  if (name === 'chat_3') return <Chat3LineIcon size={size} color={color} style={style} />;

  if (name === 'check' || name === 'checkmark') {
    return (
      <CheckIcon
        size={size}
        color={color}
        strokeWidth={strokeWidth >= 2 ? strokeWidth : STROKE_WIDTH_THICK}
      />
    );
  }

  if (name === 'close')
    return <CloseSquareCuteFilledIcon size={size} color={color} style={style} />;
  if (name === 'close-circle')
    return <CloseCircleFillIcon size={size} color={color} style={style} />;

  if (name === 'cloud') return <CloudFillIcon size={size} color={color} style={style} />;
  if (name === 'lock') return <BlockIcon size={size} color={color} />;
  if (name === 'search') return <SearchIcon size={size} color={color} style={style} />;
  if (name === 'settings_2') return <SettingsIcon size={size} color={color} style={style} />;
  if (name === 'user_x' || name === 'user-x')
    return <UserXFillIcon size={size} color={color} style={style} />;
  if (name === 'video_camera_2' || name === 'videocam')
    return <VideoCamera2FillIcon size={size} color={color} style={style} />;
  if (name === 'warning') return <WarningLineIcon size={size} color={color} style={style} />;

  if (name === 'right_small') return <ChevronRightIcon size={size} color={color} style={style} />;
  if (name === 'arrow_right') return <ArrowRightFillIcon size={size} color={color} style={style} />;
  if (name === 'up') return <ArrowUpFillIcon size={size} color={color} style={style} />;
  if (name === 'arrow_right_up' || name === 'outlink' || name === 'external-link')
    return <OutlinkIcon size={size} color={color} style={style} />;

  if (name === 'add_circle')
    return <AddSquareCuteFilledIcon size={size} color={color} style={style} />;
  if (name === 'heart') return <HeartFillIcon size={size} color={color} />;
  if (name === 'eye_close') return <EyeClosedIcon size={size} color={color} style={style} />;

  // Keep these aliases to avoid regressions while using cute assets.
  if (name === 'plus' || name === 'user_add_2')
    return <PlusIcon size={size} color={color} strokeWidth={STROKE_WIDTH_THICK} />;
  if (name === 'eye') return <ExploreIcon size={size} color={color} style={style} />;
  if (name === 'tv_2') return <ExploreIcon size={size} color={color} style={style} />;
  if (name === 'mail') return <AtLineIcon size={size} color={color} style={style} />;
  if (name === 'save') return <FollowIcon size={size} color={color} style={style} />;
  if (name === 'delete_2') return <CloseFillIcon size={size} color={color} style={style} />;

  return null;
};

export default Icon;
